int fourSumCount(const vector<int>& A, const vector<int>& B,
                 const vector<int>& C, const vector<int>& D) {
    unordered_map<long long,int> cntAB;
    for (int a : A) for (int b : B) ++cntAB[(long long)a + b];   // n^2 sums stored

    long long total = 0;
    for (int c : C) for (int d : D) {
        auto it = cntAB.find(-((long long)c + d));               // need a+b = -(c+d)
        if (it != cntAB.end()) total += it->second;
    }
    return (int)total;
}

