def four_sum_count(A: list, B: list, C: list, D: list) -> int:
    cnt_ab = {}
    for a in A:
        for b in B:
            cnt_ab[a + b] = cnt_ab.get(a + b, 0) + 1   # n^2 sums stored

    total = 0
    for c in C:
        for d in D:
            total += cnt_ab.get(-(c + d), 0)           # need a+b = -(c+d)
    return total

