void enumerateSums(const vector<long long>& w, int lo, int hi,
                   vector<long long>& out) {
    out.assign(1, 0);
    for (int i = lo; i < hi; ++i) {
        int sz = (int)out.size();
        for (int j = 0; j < sz; ++j) out.push_back(out[j] + w[i]);
    }
}

long long countSubsetsHittingX(const vector<long long>& w, long long X) {
    int n = (int)w.size(), mid = n / 2;
    vector<long long> left, right;
    enumerateSums(w, 0, mid, left);
    enumerateSums(w, mid, n, right);

    unordered_map<long long,long long> freq;      // sum -> how many right subsets
    for (long long s : right) ++freq[s];

    long long total = 0;
    for (long long s : left) {
        auto it = freq.find(X - s);
        if (it != freq.end()) total += it->second;
    }
    return total;
}

