def enumerate_sums(w: list) -> list:
    """All 2^len(w) subset sums, in O(2^k) time."""
    sums = [0]
    for x in w:
        sums += [s + x for s in sums]
    return sums


def count_subsets_hitting_x(w: list, X: int) -> int:
    mid = len(w) // 2
    left = enumerate_sums(w[:mid])
    right = enumerate_sums(w[mid:])

    freq = {}
    for s in right:
        freq[s] = freq.get(s, 0) + 1      # sum -> how many right subsets

    return sum(freq.get(X - s, 0) for s in left)

