// REFLECTION: G(n) = G(n-1), then G(n-1) reversed with the high bit set.
vector<int> grayCodeReflect(int n) {
    vector<int> res{0};
    for (int bit = 0; bit < n; ++bit) {
        // walk backwards over what exists and prefix the new bit
        for (int i = (int)res.size() - 1; i >= 0; --i)
            res.push_back(res[i] | (1 << bit));
    }
    return res;
}

// CLOSED FORM: the i-th gray code is i XOR (i >> 1).
vector<int> grayCodeFormula(int n) {
    vector<int> res;
    res.reserve(1 << n);
    for (int i = 0; i < (1 << n); ++i) res.push_back(i ^ (i >> 1));
    return res;
}

