def gray_code_reflect(n: int) -> list:
    """REFLECTION: G(n) = G(n-1), then G(n-1) reversed with the high bit set."""
    res = [0]
    for bit in range(n):
        # walk backwards over what exists and prefix the new bit
        res += [v | (1 << bit) for v in reversed(res)]
    return res


def gray_code_formula(n: int) -> list:
    """CLOSED FORM: the i-th gray code is i XOR (i >> 1)."""
    return [i ^ (i >> 1) for i in range(1 << n)]


def gray_adjacent_ok(seq: list) -> bool:
    """Self-check: consecutive entries differ in exactly one bit, and the
    sequence wraps."""
    if len(seq) < 2:
        return True
    for a, b in zip(seq, seq[1:]):
        if bin(a ^ b).count("1") != 1:
            return False
    return bin(seq[-1] ^ seq[0]).count("1") == 1

