void hanoiRec(int n, char from, char to, char aux, vector<string>& moves) {
    if (n == 0) return;
    hanoiRec(n - 1, from, aux, to, moves);              // park the tower on aux
    moves.push_back(string(1, from) + "->" + string(1, to));   // move disk n
    hanoiRec(n - 1, aux, to, from, moves);              // bring it back onto to
}

vector<string> hanoi(int n) {
    vector<string> moves;
    hanoiRec(n, 'A', 'C', 'B', moves);
    // ASSERTION: the recurrence T(n) = 2T(n-1) + 1 solves to exactly 2^n - 1
    assert(moves.size() == (size_t)((1u << n) - 1));
    return moves;
}

// Brute force: sign every element, count the assignments reaching S.
long long findTargetSumWaysBrute(const vector<int>& a, int i, long long run, int S) {
    if (i == (int)a.size()) return run == S ? 1 : 0;
    return findTargetSumWaysBrute(a, i + 1, run + a[i], S) +
           findTargetSumWaysBrute(a, i + 1, run - a[i], S);
}

// TRANSFORM: let P be the positively-signed subset and N the negative one.
//   P + N = total  and  P - N = S   =>   P = (total + S) / 2
// So the answer is the number of subsets summing to (total + S) / 2.
long long findTargetSumWays(const vector<int>& a, int S) {
    long long total = accumulate(a.begin(), a.end(), 0LL);
    if (llabs((long long)S) > total) return 0;          // unreachable
    if ((total + S) % 2 != 0) return 0;                 // ODD PARITY: impossible
    long long need = (total + S) / 2;

    vector<long long> dp(need + 1, 0);
    dp[0] = 1;
    for (int x : a)
        for (long long t = need; t >= x; --t)           // descending: 0/1 knapsack
            dp[t] += dp[t - x];
    return dp[need];
}

// OPTION 1 -- naive recursion. Dies at n ~ 10^5-10^6 depending on stack size.
//   Default stack is 8 MB on Linux, 1 MB on Windows. Each frame here is roughly
//   32-48 bytes, so 1 MB / 40 B ~ 26k frames on Windows before a stack overflow.
//   Measure with: ulimit -s   (and raise with: ulimit -s unlimited)
int lengthNaive(ListNode* node) {
    if (!node) return 0;
    return 1 + lengthNaive(node->next);
}

// OPTION 2 -- iterative conversion. The right answer for a LINEAR walk.
int lengthIterative(ListNode* head) {
    int n = 0;
    for (ListNode* t = head; t; t = t->next) ++n;
    return n;
}

// OPTION 3 -- explicit stack. Mirrors the unwind order exactly, but the frames
//   live on the HEAP, which is bounded by RAM rather than by the stack limit.
//   Use this when the traversal order genuinely matters (post-order on a tree),
//   not for a length count.
int lengthExplicitStack(ListNode* head) {
    vector<ListNode*> stack;
    for (ListNode* t = head; t; t = t->next) stack.push_back(t);
    int n = 0;
    while (!stack.empty()) { ++n; stack.pop_back(); }   // unwinds tail-first
    return n;
}

