import sys


def length_naive(head, depth_guard=None):
    """Dies with RecursionError near sys.getrecursionlimit() (default 1000)."""
    if head is None:
        return 0
    return 1 + length_naive(head.next)


def length_iterative(head) -> int:
    """The right answer for a LINEAR walk: O(1) space, no depth limit."""
    n, t = 0, head
    while t:
        n += 1
        t = t.next
    return n


def length_explicit_stack(head) -> int:
    """Frames live on the HEAP, bounded by RAM rather than the stack limit.
    Mirrors the unwind order exactly -- use when order matters (post-order
    tree walks), not for a length count."""
    stack, t = [], head
    while t:
        stack.append(t)
        t = t.next
    n = 0
    while stack:
        stack.pop()
        n += 1                  # unwinds tail-first, same order as recursion
    return n


def measure_recursion_limit(build_list) -> dict:
    """Empirically find where naive recursion dies, instead of guessing."""
    limit = sys.getrecursionlimit()
    naive_died_at = None
    for n in (100, 500, 900, 5000):
        try:
            length_naive(build_list(n))
        except RecursionError:
            naive_died_at = n
            break
    return {"recursion_limit": limit, "naive_died_at": naive_died_at}
